function finishMatch(){state='result';fireHeld=false;aimHeld=false;document.exitPointerLock?.();const won=score[0]>score[1];let rrChange=0;if(mode==='ranked'){rrChange=won?24+Math.min(10,Math.floor(player.kills/3)):-Math.min(career.rr,18);career.rr=Math.max(0,career.rr+rrChange)}career.matches++;if(won)career.wins++;career.history.unshift({mode,won,score:[...score],kills:player.kills,deaths:player.deaths,rr:rrChange,date:new Date().toISOString()});career.history=career.history.slice(0,20);save();$('touch').classList.add('hidden');$('roundBanner').classList.add('hidden');$('overlay').classList.remove('hidden');overlayType='result';const name={bomb:'爆破模式',team:'团队对战',ranked:'本地排位'}[mode];$('overlayBox').innerHTML=`<div class="eyebrow">MATCH COMPLETE / ${name}</div><h2 style="text-align:center;margin-top:20px;color:${won?'var(--lime)':'var(--red)'}">${won?'胜利 · VICTORY':'失利 · DEFEAT'}</h2><div class="result-score">${score[0]} : ${score[1]}</div><div class="result-stats"><div><b>${player.kills}</b><span>击杀</span></div><div><b>${player.deaths}</b><span>阵亡</span></div><div><b>${headshots}</b><span>爆头击杀</span></div><div><b>${totalShots?Math.round(hitShots/totalShots*100):0}%</b><span>命中率</span></div></div><p style="text-align:center">${mode==='ranked'?rankInfo(career.rr).name+' · '+(rrChange>=0?'+':'')+rrChange+' RR · 段位已保存':'战绩已保存 · 继续磨练你的枪法'}${storageOK?'':'（当前浏览器存储不可用）'}</p><div class="dialog-actions"><button class="secondary" id="resultHome">返回大厅</button><button class="primary" id="resultAgain">再来一局 ↗</button></div>`;$('resultHome').onclick=toMenu;$('resultAgain').onclick=startMatch;}
