function updateHUD(){const w=WEAPONS[weaponId()],inv=inventory[weaponId()];$('hp').textContent=Math.ceil(player.hp);$('armor').textContent=Math.ceil(player.armor);$('ammo').textContent=weaponId()==='knife'?'∞':inv.ammo;$('reserve').textContent=weaponId()==='knife'?'':'/ '+inv.reserve;$('weaponName').textContent=(weaponId()==='knife'?KNIVES[prefs.knife]:w.name)+' / '+SKINS[prefs.skin].name;$('allyScore').textContent=score[0];$('enemyScore').textContent=score[1];$('money').textContent=money.toLocaleString();$('mapLabel').textContent='青苔遗迹 / '+(mode==='team'?'团队对战':attackTeam===0?'进攻方':'防守方');$('teamAlive').innerHTML=[player,...entities.filter(b=>b.team===0)].map(e=>`<span class="agent-slot ${e.alive?'':'dead'}">${e===player?'P':'▪'}</span>`).join('');$('enemyAlive').innerHTML=entities.filter(b=>b.team===1).map(e=>`<span class="agent-slot ${e.alive?'':'dead'}">▪</span>`).join('');for(const a of['smoke','dash','heal'])$(a+'Count').textContent=abilities[a];$('touchPlant').classList.toggle('hidden',mode==='team');$('touchPlant').textContent=attackTeam===0?'下包':'拆包';$('touchBuy').textContent=mode==='team'?'武器':'购买';for(const[id,slot]of[['touchPrimary',0],['touchPistol',1],['touchSwitch',2]])$(id).classList.toggle('selected',currentSlot===slot);$('touchAim').classList.toggle('pressed',aimHeld);$('touchCrouch').classList.toggle('pressed',keys.has('ControlLeft'));}
