function mobileSettingsMarkup(){return `<details class="mobile-settings" ${touchDevice?'open':''}><summary>手机操作与陀螺仪</summary><div class="settings-row"><label for="gyroMode">陀螺仪瞄准</label><select id="gyroMode"><option value="off">关闭</option><option value="aim">仅开镜启用</option><option value="always">始终启用</option></select><span></span></div><div class="settings-row"><label for="gyroAngleOffset">陀螺仪方向修正</label><select id="gyroAngleOffset"><option value="0">自动（推荐）</option><option value="90">旋转 +90°</option><option value="-90">旋转 −90°</option><option value="180">旋转 180°</option></select><span></span></div><div class="sensor-state"><span id="gyroStatus">${gyroStatusLabels[gyro.status]}</span><button id="gyroCalibrate" class="secondary">水平校准</button><button id="gyroRetry" class="secondary">重新连接</button></div><div class="settings-row"><label for="gyroSensitivity">陀螺仪灵敏度</label><input id="gyroSensitivity" type="range" min=".25" max="4" step=".05" value="${prefs.gyroSensitivity}"><span id="gyroSensitivityValue">${prefs.gyroSensitivity.toFixed(2)}</span></div><div class="settings-row"><label for="gyroSmooth">防抖强度</label><input id="gyroSmooth" type="range" min="0" max="1" step=".05" value="${prefs.gyroSmooth}"><span id="gyroSmoothValue">${Math.round(prefs.gyroSmooth*100)}%</span></div><div class="settings-row"><label for="gyroInvert">反转陀螺仪上下</label><input id="gyroInvert" type="checkbox" ${prefs.gyroInvert?'checked':''}><span></span></div><div class="settings-row"><label for="touchSensitivity">拖屏灵敏度</label><input id="touchSensitivity" type="range" min=".3" max="2.5" step=".05" value="${prefs.touchSensitivity}"><span id="touchSensitivityValue">${prefs.touchSensitivity.toFixed(2)}</span></div><div class="settings-row"><label for="adsSensitivity">开镜灵敏度倍率</label><input id="adsSensitivity" type="range" min=".2" max="1.2" step=".02" value="${prefs.adsSensitivity}"><span id="adsSensitivityValue">${prefs.adsSensitivity.toFixed(2)}</span></div><div class="settings-row"><label for="buttonScale">按键大小</label><input id="buttonScale" type="range" min=".85" max="1.25" step=".05" value="${prefs.buttonScale}"><span id="buttonScaleValue">${Math.round(prefs.buttonScale*100)}%</span></div><div class="settings-row"><label for="buttonOpacity">按键不透明度</label><input id="buttonOpacity" type="range" min=".3" max="1" step=".01" value="${prefs.buttonOpacity}"><span id="buttonOpacityValue">${Math.round(prefs.buttonOpacity*100)}%</span></div><div class="settings-row"><label for="haptics">击杀震动反馈</label><input id="haptics" type="checkbox" ${prefs.haptics?'checked':''}><span></span></div><p>允许浏览器使用运动传感器后，将手机保持在舒服的姿势，点“水平校准”。陀螺仪可与手指拖屏同时使用。若上下、左右仍交叉，请在“方向修正”中选择旋转 +90° 或 −90°。右侧开火键可以边按边拖动瞄准，左侧开火键适合多指操作。若未收到传感器数据，请使用系统浏览器打开游戏。</p></details>`}
function bindMobileSettings(){ $('gyroAngleOffset').value=String(prefs.gyroAngleOffset);$('gyroAngleOffset').onchange=e=>{prefs.gyroAngleOffset=Number(e.target.value);gyro.setAngleOffset(prefs.gyroAngleOffset);save()};$('gyroMode').value=prefs.gyro;const connect=async()=>{const mode=$('gyroMode').value;if(mode==='off'){prefs.gyro='off';gyro.disable();save();return}const ok=await gyro.enable();if(ok){prefs.gyro=mode;save()}else{$('gyroMode').value='off';prefs.gyro='off';save()}};$('gyroMode').onchange=connect;$('gyroRetry').onclick=()=>{gyro.disable();if($('gyroMode').value==='off')$('gyroMode').value='aim';connect()};$('gyroCalibrate').onclick=()=>{gyro.calibrate();player.pitch=0;$('gyroStatus').textContent='水平已校准 · 继续保持当前握姿';haptic(8)};for(const key of['gyroSensitivity','gyroSmooth','touchSensitivity','adsSensitivity','buttonScale','buttonOpacity'])$(key).oninput=e=>{prefs[key]=+e.target.value;$(key+'Value').textContent=['gyroSmooth','buttonScale','buttonOpacity'].includes(key)?Math.round(prefs[key]*100)+'%':prefs[key].toFixed(2);applyTouchPreferences()};$('gyroInvert').onchange=e=>prefs.gyroInvert=e.target.checked;$('haptics').onchange=e=>prefs.haptics=e.target.checked;}

